import java.util.Scanner;

public class Main {
    static long countDigitsInNumber(long num) {
        num = (num < 0) ? -num : num;
        long count = 0;
        while (num != 0) {
            ++count;
            num /= 10;
        }
        return count;
    }

    static long generateSequenceOfOnes(long length) {
        long result = 0;
        for (int i = 0; i < length; ++i)
            result = result * 10 + 1;
        return result;
    }

    static long recursiveHelper2(long num) {
        if (num == 0) return 0;
        num = (num < 0) ? -num : num;
        long d = countDigitsInNumber(num);
        return d + recursiveHelper2(num - generateSequenceOfOnes(d));
    }

    static long recursiveHelper(long n, long s, long acc, long max, int[] state) {
        if (acc >= max) return max;
        if (n == 0) return acc;
        if (n < 0) { n = -n; s = -s; }
        long d = countDigitsInNumber(n);
        long ones_d = generateSequenceOfOnes(d);
        long res1 = max, res2 = max;

        if (0 <= state[(int)d] * s && -10 < state[(int)d] && state[(int)d] < 10) {
            state[(int)d] += s;
            res1 = recursiveHelper(n - ones_d, s, acc + d, max, state);
            state[(int)d] -= s;
        }
        if (0 <= state[(int)(d + 1)] * s && -10 < state[(int)(d + 1)] && state[(int)(d + 1)] < 10) {
            state[(int)(d + 1)] += s;
            res2 = recursiveHelper(n - 10 * ones_d - 1, s, acc + d + 1, res1, state);
            state[(int)(d + 1)] -= s;
        }
        return res1 < res2 ? res1 : res2;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        int[] state = new int[20];
        long maxVal = recursiveHelper2(n);
        long result = recursiveHelper(n, 1, 0, maxVal, state);
